import React, { useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
//
import { Box, TextField, Button } from "@mui/material";
import Select, { SelectChangeEvent } from "@mui/material/Select";
import AddCircleOutlineIcon from "@mui/icons-material/AddCircleOutline";
import MenuItem from "@mui/material/MenuItem";
import Link from "@mui/material/Link";
//
import { useGuildyHook } from "../api/GuildyApi";
import { useArchetypeHook } from "../api/ArchetypeApi";
import { addPersoApi, modifyPersoApi, getPersobyIdApi } from "../api/PersoApi";
import { Personnage } from "../types/All";

export const PersoFormScreen = () => {
  //
  const navigate = useNavigate();
  const { id } = useParams();
  // Remote data
  const { guildies } = useGuildyHook();
  const { classes } = useArchetypeHook();
  // Form data
  const [persoSelected, setPersoSelected] = React.useState<Personnage>();
  const [hasError, setHasError] = React.useState(false);
  const [idGuildy, setIdGuildy] = React.useState(0);
  const [idClass, setIdClass] = React.useState(0);
  const [name, setName] = React.useState("");
  const [ilvl, setIlvl] = React.useState(0);

  // Set inital data
  useEffect(() => {
    setUpData();
  }, [id]);

  const setUpData = async () => {
    if (id) {
      const perso = await getPersobyIdApi(Number(id));
      setPersoSelected(perso);
      setIdClass(perso.idClass);
      setIdGuildy(perso.idGuildy);
      setName(perso.name);
      setIlvl(perso.ilvl);
    }
  };

  // Form Handlers
  const handleGuildyChange = (event: SelectChangeEvent) => {
    setIdGuildy(Number(event.target.value));
  };

  const handleClassChange = (event: SelectChangeEvent) => {
    setIdClass(Number(event.target.value));
  };

  const handleNameChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setName(event.target.value);
  };

  const handleLevelChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setIlvl(Number(event.target.value));
  };

  //actions
  const computeError = () => {
    if (name === "" || ilvl === 0 || idGuildy === 0 || idClass === 0) {
      setHasError(true);
      return true;
    }
    setHasError(false);
    return false;
  };

  const addPerso = async () => {
    if (computeError() === true) {
      return;
    }
    await addPersoApi(name, Number(ilvl), idGuildy, idClass);
    closePersoForm();
  };

  const modifyPerso = async () => {
    if (computeError() === true) {
      return;
    }
    if (persoSelected) {
      await modifyPersoApi(
        persoSelected?.id,
        name,
        Number(ilvl),
        idGuildy,
        idClass
      );
    }
    closePersoForm();
  };

  const closePersoForm = () => {
    navigate("/personnages");
  };

  return (
    <div className="DispoForm">
      <Box
        sx={{
          justifyContent: "flex-start",
          alignItems: "flex-start",
          flexDirection: "column",
          //backgroundColor: "yellow",
          marginTop: 2,
        }}
      >
        <h2>
          {persoSelected
            ? "Modifier un perso"
            : "Formulaire d'ajout d'un perso"}
        </h2>
        <Select
          id="demo-simple-select"
          value={idGuildy.toString()}
          label="Pseudo"
          onChange={handleGuildyChange}
          variant="filled"
          sx={{ minWidth: 200 }}
        >
          <MenuItem value={0}>
            <em>Votre pseudo</em>
          </MenuItem>
          {guildies.map((member) => (
            <MenuItem key={member.id} value={member.id}>
              {member.name}
            </MenuItem>
          ))}
        </Select>
        <br />
        <i>
          * Si votre pseudo ne figure pas dans la liste, veuillez contacter
          Mélanie
        </i>
        <br />
        <br />
        <TextField
          id="filled-basic"
          label="Perso"
          variant="filled"
          value={name}
          onChange={handleNameChange}
        />
        <br />
        <br />
        <TextField
          id="filled-basic"
          label="ilvl"
          variant="filled"
          type="number"
          value={ilvl}
          onChange={handleLevelChange}
        />
        <br />
        <br />
        <Select
          id="demo-simple-select"
          value={idClass.toString()}
          label="Pseudo"
          onChange={handleClassChange}
          variant="filled"
          sx={{ minWidth: 200 }}
        >
          <MenuItem value={0}>
            <em>Votre classe</em>
          </MenuItem>
          {classes.map((member) => (
            <MenuItem key={member.id} value={member.id}>
              {member.name}
            </MenuItem>
          ))}
        </Select>
        <br />
        <br />
        {hasError === true && (
          <p className="error">Merci de remplir tous les champs</p>
        )}
        <br />
        <Button
          variant="outlined"
          startIcon={persoSelected ? null : <AddCircleOutlineIcon />}
          onClick={persoSelected ? modifyPerso : addPerso}
        >
          {persoSelected ? "Modifier" : "Ajouter"}
        </Button>
        <br />
        <br />
        <Link component="button" variant="body2" onClick={closePersoForm}>
          Retour à la liste
        </Link>
      </Box>
    </div>
  );
};
